        col += vec3(1.0, 0.62, 0.34) * (pow(s, 6.0) * 0.45 + pow(s, 90.0) * 1.4);
        gl_FragColor = vec4(col, 1.0);
      }`
  })
);
scene.add(sky);

// ---------------------------------------------------------------- lights
scene.add(new THREE.HemisphereLight(0xffb27a, 0x2a2438, 0.85));
const sun = new THREE.DirectionalLight(0xffb066, 1.5);
sun.position.copy(SUN_DIR).multiplyScalar(200);
scene.add(sun);
const rim = new THREE.DirectionalLight(0x8fa4ff, 0.35);
rim.position.set(-80, 60, 120);
scene.add(rim);
// warm fill so the pagoda keeps its red at dusk
const fill = new THREE.PointLight(0xffcf9a, 60, 60, 2);
fill.position.set(-10, 14, -6);
scene.add(fill);

